def transform(grid):
    """Extend the object on the far side of a full color-2 divider by one
    cell, drawing a parallel color-8 line when there is room."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The divider is a full row or column of color 2.
    div = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            div = ('h', r)
            break
    if div is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                div = ('v', c)
                break
    if div is None:
        return out
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    orient, pos = div
    # Locate the non-background object on either side of the divider, then
    # draw a stripe just beyond its outermost edge, if within the canvas.
    if orient == 'v':
        side = 1 if pos + 1 < w and any(grid[r][pos + 1] != bg and grid[r][pos + 1] != 2 for r in range(h)) else -1
        occupied = [c for c in range(w) if any(grid[r][c] != bg and grid[r][c] != 2 for r in range(h))]
        if not occupied:
            return out
        edge = max(occupied) if side == 1 else min(occupied)
        target = edge + side
        if 0 <= target < w and all(grid[r][target] == bg for r in range(h)):
            for r in range(h):
                out[r][target] = 8
    else:
        side = 1 if pos + 1 < h and any(grid[pos + 1][c] != bg and grid[pos + 1][c] != 2 for c in range(w)) else -1
        occupied = [r for r in range(h) if any(grid[r][c] != bg and grid[r][c] != 2 for c in range(w))]
        if not occupied:
            return out
        edge = max(occupied) if side == 1 else min(occupied)
        target = edge + side
        if 0 <= target < h and all(grid[target][c] == bg for c in range(w)):
            out[target] = [8] * w
    return out

